"""Standalone research report and standard chart artifacts from frozen results."""
from pathlib import Path
import json,html,csv
from reportlab.graphics.shapes import Drawing,String
from reportlab.graphics.charts.lineplots import LinePlot
from reportlab.lib import colors
from reportlab.graphics import renderSVG
R=Path(__file__).resolve().parent
E=html.escape
def pct(v):return '—' if v is None else f'{v*100:.2f}%'
def num(v):return '—' if v is None else f'{v:.3f}'
def cash(v):return f'${v:,.2f}'
def ci(v):return '—' if not v or v[0] is None else f'{v[0]*100:.1f}–{v[1]*100:.1f}%'
def settings(m):
 if 'components' in m:return ('Agreement: ' if m['rule']=='agree' else 'Vote: ')+' + '.join(settings(c) for c in m['components'])
 reverse=' inverted' if m.get('orientation')==-1 else ''
 if m['id'].startswith('ST:'):return f"{m['tf']}m Stoch({m['n']},{m['k']},{m['d']}) {m['rule']}{reverse}"
 return f"{m['tf']}m SMA({m['fast']},{m['slow']}) {m['rule']}{reverse}"
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+E(str(h))+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+E(str(c))+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def chart(data,filename):
 draw=Drawing(760,310);plot=LinePlot();plot.x=55;plot.y=45;plot.width=650;plot.height=230;plot.joinedLines=1;plot.xValueAxis.valueMin=0;plot.xValueAxis.valueMax=45;plot.xValueAxis.valueSteps=[0,15,30,45];plot.yValueAxis.valueMin=40;plot.yValueAxis.valueMax=100;plot.yValueAxis.valueSteps=[40,50,60,70,80,90,100]
 series=[];labels=[]
 for fam,color in [('stochastic','#4f46e5'),('sma','#0891b2'),('mixed_combination','#c2410c')]:
  points=[]
  for off in (0,15,30,45):
   c=data['selected'].get(f'{fam}/offset{off}')
   if c and c['evaluation']['accuracy'] is not None:points.append((off,c['evaluation']['accuracy']*100))
  series.append(points);labels.append((fam.replace('_combination',''),color))
 points=[(off,data['baselines'][str(off)]['spot_strike']['accuracy']*100) for off in (0,15,30,45) if data['baselines'][str(off)]['spot_strike']['accuracy'] is not None];series.append(points);labels.append(('current price versus strike/open','#64748b'))
 plot.data=series
 for i,(_,color) in enumerate(labels):plot.lines[i].strokeColor=colors.HexColor(color);plot.lines[i].strokeWidth=2
 draw.add(plot);draw.add(String(270,12,'Entry minutes after hour start',fontSize=10));draw.add(String(3,292,'Accuracy (%)',fontSize=10))
 for i,(label,color) in enumerate(labels):draw.add(String(60+i*170,285,label,fontSize=9,fillColor=colors.HexColor(color)))
 renderSVG.drawToFile(draw,str(R/filename))

def main():
 targets={'Kalshi':json.loads((R/'results.json').read_text()),'Polymarket':json.loads((R/'polymarket/results.json').read_text())};paper=json.loads((R/'paper-results.json').read_text());verification=json.loads((R/'verification.json').read_text())
 parts=['''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hourly BTC — stochastic, SMA and combinations</title><style>body{font:16px/1.58 system-ui,sans-serif;color:#16243b;max-width:1180px;margin:40px auto;padding:0 24px;background:#f8fafc}h1{font-size:38px;line-height:1.15;max-width:900px}h2{margin-top:44px;border-bottom:1px solid #cbd5e1;padding-bottom:9px}h3{margin-top:28px}p{max-width:1000px}.eyebrow{color:#64748b;letter-spacing:.1em;text-transform:uppercase;font-size:12px}.callout{padding:18px 22px;border-left:4px solid #4f46e5;background:#eef2ff;margin:24px 0}.warning{background:#fff7ed;border-color:#c2410c}.scroll{overflow:auto}table{border-collapse:collapse;background:white;width:100%;font-size:13px;margin:15px 0}th,td{padding:10px 12px;border-bottom:1px solid #e2e8f0;text-align:left;vertical-align:top}th{background:#e2e8f0;white-space:nowrap}td:first-child{font-weight:550}details{background:white;padding:12px 18px;margin:14px 0;border:1px solid #e2e8f0}summary{cursor:pointer;font-weight:600}img{width:100%;height:auto;background:white}a{color:#4338ca}code{font-size:13px}.muted{color:#64748b;font-size:14px}nav a{margin-right:20px}footer{border-top:1px solid #cbd5e1;margin-top:40px;padding-top:20px}</style><p class="eyebrow">NeoRome research · 18 October 2026 · Historical simulation</p><h1>Hourly BTC: stochastic, SMA and combined signals</h1><p>Two different contracts. Four chart timeframes. Four entry times. Separate parameter selection for each target.</p><nav><a href="#results">Results</a><a href="#kalshi">Kalshi</a><a href="#polymarket">Polymarket</a><a href="#profit">Profit test</a><a href="#method">Method & limits</a><a href="#files">Files</a></nav>''']
 parts.append('<div class="callout"><strong>What this test establishes.</strong> It identifies the strongest validation-selected settings within a finite, declared search. The evaluation covers September 13–October 17, 2026. This calendar period was already inspected in earlier 15-minute research, so these are exploratory results, not an untouched confirmatory test.</div>')
 rows=[]
 for venue,data in targets.items():
  for fam in ('stochastic','sma','mixed'):
   c=data['selected']['overall/'+fam];m=c['evaluation'];rows.append([venue,fam,c['meta']['offset'],settings(c['meta']),f"{m['wins']}/{m['active']}",pct(m['accuracy']),ci(c['bootstrap']['accuracy95']),pct(m['coverage']),num(m['correlation'])])
 parts.append('<h2 id="results">Selected strategies: final chronological evaluation</h2>'+table(['Target','Family','Entry +min','Selected settings','Correct / active','Accuracy','95% daily-block interval','Opportunity coverage','Correlation'],rows))
 parts.append('<p>Each row was selected using validation correlation before evaluating this period. “Pure stochastic” and “pure SMA” may combine several charts using only that indicator family. “Mixed” combines stochastic and SMA signals. A high accuracy on a small active subset is not directly comparable to a high-coverage strategy.</p>')
 for venue,data in targets.items():
  anchor=venue.lower();d=data['data'];parts.append(f'<h2 id="{anchor}">{venue}: target, sample and entry timing</h2>')
  description='YES if the final 60-second BRTI average is above the fixed strike; NO otherwise. One contract per hour, chosen by minimum absolute distance between its listed strike and the preceding Coinbase close. Only contracts listed/opened before the hour are eligible. The selected contract stays fixed across all entry times.' if venue=='Kalshi' else 'UP if the Binance BTC/USDT one-hour candle closes at or above its opening trade; DOWN otherwise. Features use Binance candles. Labels come from official resolved Polymarket payouts, and all retained labels agree with Binance open/close direction.'
  parts.append('<p>'+description+'</p>');parts.append(table(['Usable hours','Training','Validation','Evaluation','Missing 5m input bars'],[[d['selected_hours'],d['counts']['train'],d['counts']['validation'],d['counts']['evaluation'],d['missing_5m_bars']]]))
  fname=anchor+'-accuracy.svg';chart(data,fname);parts.append(f'<img src="{fname}" alt="{venue} evaluation accuracy by entry minute"><p class="muted">Lines connect separately selected strategies at each entry time; they are not one model improving over time. The price-versus-strike/open baseline uses all available hours, so use the matched-trade comparisons below for fair assessment.</p>')
  rows=[]
  for off in (0,15,30,45):
   for fam in ('stochastic','sma','mixed_combination'):
    c=data['selected'].get(f'{fam}/offset{off}')
    if not c:continue
    m=c['evaluation'];paired=c['spot_on_same_trades'];rows.append([off,fam.replace('_combination',''),settings(c['meta']),pct(c['train']['accuracy']),pct(c['validation']['accuracy']),pct(m['accuracy']),m['active'],pct(paired['accuracy']) if paired else '—',pct(c['paired_accuracy_advantage_vs_spot']),ci(c['bootstrap']['paired_accuracy_advantage95'])])
  parts.append(table(['+min','Family','Settings','Train accuracy','Validation accuracy','Evaluation accuracy','Active hours','Price baseline on same hours','Accuracy difference','Difference 95% interval'],rows))
  if venue=='Polymarket':
   c=data['selected']['overall/stochastic']['meta']
   if c.get('tf')==15 and c.get('k')==1 and c.get('d')==3 and c.get('rule')=='d_slope':
    parts.append('<p><strong>Why the long-lookback stochastic can be accurate late.</strong> With three-period D smoothing, D(t)−D(t−1) equals [K(t)−K(t−3)]/3. On a 15-minute chart, this compares K now with K 45 minutes earlier. When the longer high/low range is stable, its sign often tracks the move already observed during the hour. That explains why a high late-entry win rate can add little beyond the current-price baseline.</p>')
  parts.append('<p class="muted">The difference is strategy accuracy minus the contemporaneous price-versus-strike/open baseline on identical active hours. Negative values mean the simple baseline was better. Polymarket’s opening price is not available before its first hourly trade, so the minute-0 baseline is omitted. Confidence intervals are unadjusted for the very large research search.</p>')
  rows=[]
  for off in (0,15,30,45):
   for tf in (15,30,45,60):
    for fam in ('stochastic','sma'):
     c=data['selected'].get(f'{fam}/chart{tf}/offset{off}')
     if not c:rows.append([off,tf,fam,'No eligible training shortlist candidate',*(['—']*6)]);continue
     m=c['evaluation'];rows.append([off,tf,fam,settings(c['meta']),num(c['train']['correlation']),num(c['validation']['correlation']),num(m['correlation']),pct(m['accuracy']),m['active'],pct(m['coverage'])])
  parts.append('<details><summary>Every chart timeframe and entry offset: pure single-chart winners</summary>'+table(['+min','Chart min','Family','Settings','Train corr.','Validation corr.','Evaluation corr.','Accuracy','Active','Coverage'],rows)+'</details>')
  rows=[]
  for fam in ('stochastic','sma','mixed'):
   c=data['selected']['overall/'+fam];rows.append([fam,*[f"{pct(m['accuracy'])} ({m['active']} signals)" for m in c['thirds']]])
  parts.append('<h3>Stability inside the evaluation period</h3>'+table(['Family','First third','Middle third','Final third'],rows))
  rows=[]
  for tf in (15,30,45,60):
   for pair in ('2-5','5-10'):
    for rule in ('state','cross'):
     for off in (0,45):
      c=data['selected'][f'control/{tf}/{pair}/{rule}/{off}'];m=c['evaluation'];rows.append([tf,pair,rule,off,pct(m['accuracy']),m['active'],num(m['correlation'])])
  parts.append('<details><summary>Earlier SMA 2/5 and 5/10 settings as fixed controls</summary>'+table(['Chart min','Lengths','Rule','+min','Accuracy','Active','Correlation'],rows)+'<p>Offsets +15 and +30 are also retained in the machine-readable results.</p></details>')
 parts.append('<h2 id="profit">Do the selected Kalshi strategies make money?</h2><p>Three separate internal paper accounts start at $500. Each trade uses at most 25% of current settled cash including taker fees, with integer contracts, at most one unsettled position, and settlement at the recorded official timestamp. Entries use the recorded YES ask or 1−YES bid one minute after the signal. These are hypothetical full fills; historical queue position and available size were not established.</p>')
 rows=[]
 for a in paper['accounts']:rows.append([a['strategy'],a['scenario'],a['trades'],pct(a['win_rate']),cash(a['ending_cash']),cash(a['net_pnl']),cash(a['fees']),f"{a['max_settled_balance_drawdown_pct']:.1f}%"])
 parts.append(table(['Family','Cost scenario','Trades','Win rate','Ending cash','Net profit','Fees','Max settled-balance drawdown'],rows))
 rows=[]
 for fam,s in paper['unit_shadows'].items():rows.append([fam,s['signals'],pct(s['win_rate']),f"{s['mean_price']*100:.3f}¢",f"{s['mean_fee']*100:.3f}¢",f"{(s['mean_price']+s['mean_fee'])*100:.3f}%",f"{s['mean_net']*100:+.3f}¢",f"{s['mean_net_daily_block95'][0]*100:+.3f} to {s['mean_net_daily_block95'][1]*100:+.3f}¢"])
 mixed_signal=targets['Kalshi']['selected']['overall/mixed']['evaluation'];mixed_shadow=paper['unit_shadows']['mixed'];mixed_account=next(a for a in paper['accounts'] if a['strategy']=='mixed' and a['scenario']=='delayed_close')
 parts.append(f'<p><strong>Why the win rates differ.</strong> The mixed signal was correct on {mixed_signal["wins"]}/{mixed_signal["active"]} hours ({pct(mixed_signal["accuracy"])}). Only {mixed_shadow["signals"]} had an eligible delayed entry price between zero and one dollar; those won {pct(mixed_shadow["win_rate"])}. Their mean price plus fee required {pct(mixed_shadow["mean_price"]+mixed_shadow["mean_fee"])} to break even. The finite account completed {mixed_account["trades"]} trades before depletion and other skips, winning {pct(mixed_account["win_rate"])} of that different subset. A high signal win rate is therefore not the same as a profitable account win rate.</p>')
 parts.append('<h3>One contract on every eligible signal</h3><p>This separate reference ignores cash depletion and the account’s single-position constraint. It shows whether the underlying signals earned money at quoted prices across the full evaluation sample.</p>'+table(['Family','Signals','Win rate','Mean price','Mean fee','Average break-even rate','Mean net / contract','Net 95% interval'],rows))
 primary=[a for a in paper['accounts'] if a['scenario']=='delayed_close'];positive=[a['strategy'] for a in primary if a['net_pnl']>0]
 conclusion=('The primary replay finished above $500 for: '+', '.join(positive)+'. This remains a historical, hypothetical-fill result requiring fresh forward validation.') if positive else 'None of the three primary Kalshi accounts finished above its initial $500. Higher directional accuracy did not establish a profitable entry-price edge.'
 parts.append('<div class="callout warning">'+conclusion+' Polymarket profitability is unverified: its public historical-price records do not establish executable historical asks or depth. No actual-price Polymarket account result is fabricated.</div>')
 parts.append('''<h2 id="method">What was searched and how winners were selected</h2><p>For each target: stochastic lookback 5–100 candles, K smoothing 1–5 and D smoothing 1–5; eight rules and normal/inverted orientations. SMA tests every pair 2≤fast&lt;slow≤200, with state and fresh crossover rules, normal/inverted. Each is tested on 15-, 30-, 45- and 60-minute candles at entries +0, +15, +30 and +45. That is 1,875,264 single-chart variants per target, 3,750,528 total. Degenerate and duplicate variants count as searched; shortlists deduplicate identical training decisions.</p><p>Stochastic rules: level around 50, K−D direction, K slope, D slope, fresh K/D crossover, and rising from a previous K at/below 10/20/30 or falling from at/above 90/80/70. The latter are zone events, not necessarily local reversals. “Inverted” means reversing the conventional signal. SMA state means fast above/below slow; crossover fires only on a fresh sign change.</p><p>Only complete source candles are allowed. 45-minute candles use fixed UTC epoch boundaries; they do not restart at each market hour. State signals carry from the latest completed candle, while event signals fire only at an exact source-candle close. Thus a 60-minute state cannot gain new information within an hour. Missing input bars remain missing, including the Coinbase gap on May 8; longer affected lookbacks abstain.</p><p>Training is April 21–August 6; August 7 is an embargo. Validation is August 8–September 11; September 12 is an embargo. Labels must settle before the respective cutoff. Evaluation is September 13–October 17. For each family/chart/offset, retain the ten best distinct training decision sequences with positive training correlation and at least 200 active signals. Validation chooses among them with at least 50 active signals. The ranking score is Pearson correlation between signed decisions and official outcomes, with zero for abstention and missing excluded. It is coverage-sensitive and is not a probability estimate.</p><p>Combinations exhaustively pair the top five training candidates per family/chart/offset: same-family pairs across charts and all stochastic–SMA pairs. Agreement requires equal nonzero directions; voting takes the sign of the sum, allowing one component to abstain. Additional three/four-chart unanimous combinations use each family/chart’s top training candidate. The combination search is exhaustive within these declared shortlists, not over the full cross-product of millions of raw settings. Family winners can select their entry offset using validation only. Settings and prediction arrays are hashed and saved before evaluation.</p>''')
 parts.append('<p>Combination trial counts: '+', '.join(f'{venue} {data["combination_trials"]:,}' for venue,data in targets.items())+'. Confidence intervals resample whole UTC days 2,000 times. The sample has only 35 evaluation days; rare rules have much less information. A large grid, a short validation period and prior inspection of this calendar range all increase overfitting risk. No strategy is promoted to live trading.</p>')
 parts.append('''<h3>Limits that matter</h3><ul><li>These are two different settlement targets and two different feature feeds; their win rates are not interchangeable.</li><li>The price/strike baseline is a necessary comparison for late entries: the market often prices in the same information that improves accuracy.</li><li>Final market metadata are retrospective snapshots. Original strike publication/revisions and later outcome revisions cannot be reconstructed completely.</li><li>Kalshi uses Coinbase as a feature proxy for its BRTI settlement index; Polymarket uses its stated Binance source. Missing markets and exclusions are listed in the data summaries.</li><li>The 25% position allocation is the user-specified experiment. Compounding, occasional losses and fee drag can substantially change a small account even when signal accuracy looks favorable.</li><li>All thresholds, tested ranges and selection decisions are finite. “Best” means validation-selected within this experiment, not the best possible strategy.</li></ul><p>An independent audit caught a floating-point equality error in one initial SMA diagnostic. Both entire searches were rerun using exact cent-valued sums, with unchanged rules. First-attempt outputs are retained; this correction does not restore an untouched holdout.</p><h3>Verification</h3>''')
 parts.append('<p>Seven focused timing/scoring tests passed. Independent array/window calculations reconstructed '+f"{verification['kalshi']['independently_reconstructed_cells']+verification['polymarket']['independently_reconstructed_cells']:,}"+' saved signal cells, verified declared trial counts across '+f"{verification['kalshi']['trial_rows']+verification['polymarket']['trial_rows']:,}"+' single-chart trial records and chronological masks, and matched final win counts. Exact rational arithmetic independently audited '+f"{verification['cash']['trades']:,}"+' paper trades and '+f"{verification['cash']['cash_events']:,}"+' cash events. Read-only independent review checked the target rules, timing, selection and accounting integration.</p>')
 parts.append('''<h2 id="files">Reproducible artifacts</h2><p><a href="EXPERIMENT.md">Frozen protocol</a> · <a href="results.json">Kalshi full results</a> · <a href="polymarket/results.json">Polymarket full results</a> · <a href="paper-results.json">Paper accounts</a> · <a href="verification.json">Verification</a> · <a href="manifest.json">Input/code hashes</a> · <a href="selection-lock.json">Kalshi selection lock</a> · <a href="polymarket/selection-lock.json">Polymarket selection lock</a></p><p>Full compressed trial tables, training shortlists, selected market records, account ledgers and raw public response caches are saved alongside this report. Scripts: study.py, evaluate.py, paper.py, verify.py and the collection scripts.</p><h3>Primary sources</h3><ul><li><a href="https://assets.kalshi.com/contract_terms/BTC.pdf">Kalshi Bitcoin contract terms</a> and cached KXBTCD rules/outcomes from the official API.</li><li><a href="https://docs.kalshi.com/api-reference/historical/get-historical-markets">Kalshi historical markets</a> and <a href="https://docs.kalshi.com/api-reference/market/batch-get-market-candlesticks">historical quote candles</a>.</li><li><a href="https://kalshi.com/docs/kalshi-fee-schedule.pdf">Kalshi fee schedule</a> and <a href="https://docs.kalshi.com/getting_started/fee_rounding">rounding rules</a>. Cached series/event checks found no applicable KXBTCD fee overrides.</li><li><a href="https://polymarket.com/event/bitcoin-up-or-down-october-1-2026-7am-et">Official Polymarket hourly settlement rule example</a> and <a href="https://docs.polymarket.com/api-reference/events/list-events">Gamma event API</a>.</li><li><a href="https://developers.binance.com/docs/binance-spot-api-docs/rest-api/market-data-endpoints">Binance candle API</a> and <a href="https://docs.cdp.coinbase.com/api-reference/exchange-api/rest-api/products/get-product-candles">Coinbase candle API</a>.</li><li><a href="https://docs.polymarket.com/market-data/prices-order-books">Polymarket prices/order books</a> and <a href="https://docs.polymarket.com/trading/fees">fees</a>: historical marks are not an executable bid/ask archive.</li></ul><footer class="muted">Historical research only. No orders, transfers, deployed changes or broker permission changes. Canonical research provenance is stored with cloud-record.json when recording succeeds.</footer></html>''')
 (R/'report.html').write_text('\n'.join(parts));print('report generated',R/'report.html')
if __name__=='__main__':main()
